/* Eyeblink admin · team — loaded after the files before it; all of admin/js shares one scope */
  /* ================= the team: applications → trial → account → collaboration agreement → tasks → review → pay ================= */
  var TEAM=null, TSUB='tasks', TOPEN=null;
  var TROLE={editor:'مونتير',motion:'موشن ديزاينر',color:'كولوريست',sound:'مهندس صوت',writer:'كاتب محتوى',shooter:'مصوّر',designer:'مصمم',producer:'منسّق إنتاج',voice:'معلّق صوتي',illustrator:'رسّام',social:'مدير سوشال ميديا',subtitles:'مترجم ومحرّر نصوص',support:'دعم العملاء',marketing:'مدير تسويق'};
  var STAFF_ROLES=['support','marketing'], TTYPE={freelance:'مستقل',staff:'موظف'};
  var TFIELDS=[['gender','الجنس (ذكر/أنثى)'],['phone','واتساب'],['city','المدينة والدولة'],['langs','اللغات'],['reel','رابط الشوريل'],['links','روابط أعمال أخرى'],['tools','الأدوات'],['about','سطور عنه']];
  var TAPP={new:'جديد',trial:'مهمة تجريبية',interview:'مقابلة',accepted:'مقبول',rejected:'مرفوض'};
  var TTST={assigned:'جديدة',progress:'قيد العمل',changes:'تعديلات مطلوبة',qc:'بانتظار مراجعتك',approved:'معتمدة',declined:'اعتذر عنها'};
  function loadTeam(){ if(!LIVE){ TEAM={err:'live',apps:[],members:[],tasks:[],settings:{}}; if(TAB==='team') renderTeam(); return; }
    fetch(API+'/team?admin=1',{headers:headers({}),cache:'no-store'}).then(function(r){ return r.json(); }).then(function(j){ TEAM=j.ok?j:{err:j.error||'fail',apps:[],members:[],tasks:[],settings:{}}; renderTabs(); if(TAB==='team') renderTeam(); if(TOPEN) openTTask(TOPEN); })
      .catch(function(){ TEAM={err:'net',apps:[],members:[],tasks:[],settings:{}}; if(TAB==='team') renderTeam(); }); }
  function treq(body,btn,ok){ if(btn) btn.disabled=true; return api('/team','POST',body).then(function(j){ if(!j.ok) throw new Error(j.error||'fail'); if(ok) toast(ok); return j; })
    .catch(function(err){ if(btn) btn.disabled=false; toast(({exists:'لهذا البريد حساب في الفريق مسبقاً',email:'البريد الإلكتروني غير صحيح',title:'اكتب عنوان المهمة',member:'اختر عضو الفريق'})[err.message]||'تعذّر ذلك، حاول مرة أخرى',true); throw err; }); }
  function memName(e){ var m=TEAM&&TEAM.members.filter(function(x){return x.email===e})[0]; return m?m.name:e; }
  function renderTeam(){
    renderTabs(); if(!TEAM){ $('#panel').innerHTML='<div class="sec"><div class="empty">جارٍ التحميل…</div></div>'; loadTeam(); return; }
    if(TEAM.err==='live'){ $('#panel').innerHTML='<div class="sec"><div class="empty">يعمل قسم الفريق على الموقع المنشور</div></div>'; return; }
    var na=TEAM.apps.filter(function(a){return a.status==='new'}).length, qc=TEAM.tasks.filter(function(t){return t.status==='qc'}).length;
    var subs=[['tasks','المهام',qc],['members','الأعضاء',0],['apps','طلبات الانضمام',na],['settings','التوظيف',0]];
    var head='<div class="subtabs">'+subs.map(function(s){ return '<button type="button" data-tsub="'+s[0]+'"'+(TSUB===s[0]?' aria-current="true"':'')+'>'+s[1]+(s[2]?'<span class="count hot">'+s[2]+'</span>':'')+'</button>'; }).join('')+'</div>';
    var t0=todayISO(), T=TEAM.tasks, live=function(x){ return ['assigned','progress','changes'].indexOf(x.status)>=0; };
    var owed=T.filter(function(x){ return x.status==='approved'&&!(x.payout&&x.payout.paid); }).reduce(function(s,x){ return s+(+x.fee||0); },0);
    var kpis='<section class="sec kcsec"><div class="kcs">'+kc(T.filter(live).length,'مهام عند الفريق','prod','k_play')+kc(qc,'بانتظار مراجعتك','sign','k_done')+
      kc(T.filter(function(x){ return live(x)&&x.due&&x.due<t0; }).length,'متأخرة','bad','k_late')+kc('<span dir="ltr">'+esc(pfmt(owed,'$'))+'</span>','أجور مستحقة','fix','payments',owed>0)+kc(na,'طلبات انضمام جديدة','new','team')+'</div></section>';
    $('#panel').innerHTML=kpis+head+({tasks:teamTasks,members:teamMembers,apps:teamApps,settings:teamSettings})[TSUB]();
  }
  function teamTasks(){
    var cols=[['assigned','جديدة',['assigned']],['progress','قيد العمل',['progress','changes']],['qc','بانتظار مراجعتك',['qc']],['approved','معتمدة',['approved']]], t0=todayISO();
    var due=TEAM.tasks.filter(function(t){ return t.status==='approved'&&!(t.payout&&t.payout.paid); }).reduce(function(a,t){ return a+(+t.fee||0); },0);
    return '<div class="board-h"><span class="muted small">يرى عضو الفريق مهمته وأجره فقط، ولا يصله اسم العميل ولا أسعاره</span><button class="btn primary sm" type="button" data-tnew>+ مهمة</button></div>'+
      '<div class="board">'+cols.map(function(c){ var l=TEAM.tasks.filter(function(t){ return c[2].indexOf(t.status)>=0; });
        return '<div class="bcol st-'+c[0]+'"><h4><i></i>'+c[1]+'<small>'+l.length+'</small></h4>'+(l.length?l.map(function(t){ var late=t.due&&t.due<t0&&t.status!=='approved'&&t.status!=='qc';
          return '<button type="button" class="bcard st-'+t.status+'" data-ttask="'+esc(t.id)+'"><b>'+esc(t.title)+'</b><span class="muted small">'+esc(memName(t.member))+(t.alias?' · '+esc(t.alias):'')+'</span><div class="bmeta"><span class="'+(late?'c-crit':'')+'">'+(t.due?esc(fdate(t.due)):'بلا موعد')+'</span><span dir="ltr">'+esc(pfmt(+t.fee||0,t.cur||'$'))+'</span></div>'+
            (t.status==='changes'?'<em class="tag c-warn">تعديلات</em>':'')+(t.status==='approved'?'<em class="tag '+(t.payout&&t.payout.paid?'c-good':'c-warn')+'">'+(t.payout&&t.payout.paid?'صُرف':'مستحق')+'</em>':'')+'</button>'; }).join(''):'<div class="bempty">—</div>')+'</div>'; }).join('')+'</div>';
  }
  function teamMembers(){
    if(!TEAM.members.length) return '<div class="sec"><div class="empty">لا أعضاء في الفريق بعد. اقبل طلب انضمام، أو أضف عضواً مباشرة</div><div class="actions" style="justify-content:center"><button class="btn primary" type="button" data-tmadd>+ عضو</button></div></div>'+tAddForm();
    return '<div class="board-h"><span class="muted small">'+(function(n){ return n===1?'عضو واحد':n===2?'عضوان':n<=10?n+' أعضاء':n+' عضواً'; })(TEAM.members.length)+'</span><button class="btn sm" type="button" data-tmadd>+ عضو</button></div>'+tAddForm()+'<div class="mgrid">'+TEAM.members.filter(function(m){return m.status!=='removed'}).map(function(m){
      var ts=TEAM.tasks.filter(function(t){ return t.member===m.email; }), open=ts.filter(function(t){ return t.status!=='approved'; }).length, due=ts.filter(function(t){ return t.status==='approved'&&!(t.payout&&t.payout.paid); }).reduce(function(a,t){ return a+(+t.fee||0); },0);
      var ct=m.contract, cs=!ct?'<em class="tag c-warn">بلا اتفاقية</em>':ct.signedAt?'<em class="tag c-good">الاتفاقية موقّعة</em>':'<em class="tag c-info">الاتفاقية مرسلة</em>';
      return '<div class="mcard"><div class="mh"><span class="av">'+esc(String(m.name).trim().charAt(0))+'</span><div><b>'+esc(m.name)+'</b><span class="muted small">'+esc(TROLE[m.role]||m.role)+' · '+(TTYPE[m.type||'freelance'])+(m.type==='staff'&&m.salary?' · '+esc(pfmt(m.salary.amount,m.salary.cur))+' شهرياً':'')+(m.status==='paused'?' · موقوف':'')+'</span></div>'+cs+'</div>'+
        '<div class="mstats"><div><b>'+open+'</b><span>مهام مفتوحة</span></div><div><b dir="ltr">'+esc(pfmt(due,'$'))+'</b><span>مستحق</span></div><div><b>'+ts.filter(function(t){return t.status==='approved'}).length+'</b><span>منجزة</span></div></div>'+
        '<div class="small muted" dir="ltr" style="text-align:end">'+esc(m.email)+(m.phone?' · '+esc(m.phone):'')+'</div>'+
        '<details class="mpay"><summary class="small">النوع والراتب</summary><form data-mtyp="'+esc(m.email)+'"><div class="row"><div class="field"><label>نوع العلاقة</label><select name="mtype" data-mtype>'+Object.keys(TTYPE).map(function(k){ return '<option value="'+k+'"'+((m.type||'freelance')===k?' selected':'')+'>'+TTYPE[k]+'</option>'; }).join('')+'</select></div><div class="field" data-salary'+(m.type==='staff'?'':' hidden')+'><label>الراتب الشهري</label><input name="salary" dir="ltr" value="'+esc(m.salary?m.salary.amount:'')+'"></div>'+staffFields(m,m.type==='staff')+'<div class="field" data-salary'+(m.type==='staff'?'':' hidden')+' style="max-width:200px"><label>العملة</label>'+curSel('name="salaryCur"',(m.salary&&m.salary.cur)||'$')+'</div></div><div class="actions"><button class="btn sm" type="submit">حفظ</button></div></form></details>'+
        '<details class="mpay"><summary class="small">طريقة الصرف: '+esc(payText(m,'ar','حسب إعدادات المستندات'))+'</summary><form data-mpay="'+esc(m.email)+'">'+payFields(m.pay)+'<div class="actions"><button class="btn sm" type="submit">حفظ</button></div></form></details>'+
        '<div class="dl2"><button class="btn sm primary" type="button" data-tnew data-for="'+esc(m.email)+'">+ مهمة</button>'+
          (!ct||!ct.signedAt?'<button class="btn sm" type="button" data-tcontract="'+esc(m.email)+'">'+(ct?'أعد إرسال الاتفاقية':'أعدّ الاتفاقية')+'</button>':'<a class="btn sm" target="_blank" rel="noopener" href="/team-agreement/'+esc(ct.token)+'">الاتفاقية</a>')+
          (due?'<button class="btn sm" type="button" data-tpayall="'+esc(m.email)+'">سجّل صرف المستحق</button>':'')+
          '<button class="btn sm" type="button" data-treset="'+esc(m.email)+'">كلمة سر مؤقتة</button><button class="btn sm" type="button" data-tpause="'+esc(m.email)+'">'+(m.status==='paused'?'تفعيل':'إيقاف')+'</button></div></div>'; }).join('')+'</div>';
  }
  function tAddForm(prefill){ prefill=prefill||{}; return '<form class="sec tadd" id="tAdd" hidden><h3>عضو جديد في الفريق</h3><div class="row"><div class="field"><label>الاسم</label><input name="name" value="'+esc(prefill.name||'')+'"></div><div class="field"><label>الإيميل</label><input name="email" type="email" dir="ltr" value="'+esc(prefill.email||'')+'"></div><div class="field"><label>الدور</label><select name="role">'+Object.keys(TROLE).map(function(r){ return '<option value="'+r+'"'+(prefill.role===r?' selected':'')+'>'+TROLE[r]+'</option>'; }).join('')+'</select></div></div><div class="row"><div class="field"><label>واتساب</label><input name="phone" dir="ltr" value="'+esc(prefill.phone||'')+'"></div><div class="field"><label>الأجر المتفق (ملاحظة)</label><input name="rate" value="'+esc(prefill.rate||'')+'"></div></div>'+payFields()+'<div class="row"><div class="field"><label>نوع العلاقة</label><select name="mtype" data-mtype>'+Object.keys(TTYPE).map(function(k){ return '<option value="'+k+'"'+((STAFF_ROLES.indexOf(prefill.role)>=0?'staff':'freelance')===k?' selected':'')+'>'+TTYPE[k]+(k==='staff'?' (راتب شهري)':' (أجر لكل مهمة)')+'</option>'; }).join('')+'</select></div><div class="field" data-salary'+(STAFF_ROLES.indexOf(prefill.role)>=0?'':' hidden')+'><label>الراتب الشهري</label><input name="salary" dir="ltr" placeholder="600"></div>'+staffFields({},STAFF_ROLES.indexOf(prefill.role)>=0)+'<div class="field" data-salary'+(STAFF_ROLES.indexOf(prefill.role)>=0?'':' hidden')+' style="max-width:200px"><label>العملة</label>'+curSel('name="salaryCur"','$')+'</div></div><input type="hidden" name="app" value="'+esc(prefill.app||'')+'"><div class="actions"><button class="btn primary" type="submit">إنشاء الحساب</button></div></form>'; }
  function teamApps(){
    if(!TEAM.apps.length) return '<div class="sec"><div class="empty">لا توجد طلبات انضمام. فعّل التوظيف من «التوظيف»، وصفحة التقديم هي <a href="/join" target="_blank" rel="noopener noreferrer" dir="ltr">/join</a></div></div>';
    var sel=TAOPEN&&TEAM.apps.filter(function(x){ return x.id===TAOPEN; })[0];
    return '<div class="osplit'+(sel?' has-open':'')+'"><ul class="olist"><li class="olh">طلبات الانضمام · '+TEAM.apps.length+'</li>'+TEAM.apps.map(appRow).join('')+'</ul>'+
      (sel?'<div class="order item odetail tf-'+(AFAM[sel.status]||'new')+'"><div class="odh"><button class="btn sm oback" type="button" data-aback>‹ كل الطلبات</button><span class="tag">'+esc(TAPP[sel.status])+'</span><b>'+esc(sel.name)+'</b><span class="muted small">'+esc(TROLE[sel.role]||sel.role)+(sel.city?' · '+esc(sel.city):'')+' · '+esc(adate(sel.at))+'</span></div>'+appBody(sel)+'</div>'
        :'<div class="odetail empty-sel">اختر طلباً من القائمة</div>')+'</div>';
  }
  // a join request's state → its colour family
  var AFAM={new:'new',trial:'prod',interview:'sign',accepted:'ok',rejected:'off'}, TAOPEN=null;
  function adate(at){ return new Date(at).toLocaleDateString('ar-u-nu-latn',{day:'numeric',month:'short'}); }
  function appRow(a){ return '<li><button type="button" class="orow st tf-'+(AFAM[a.status]||'new')+(a.id===TAOPEN?' on':'')+'" data-aopen="'+esc(a.id)+'">'+
      '<span class="orow-m"><b>'+esc(a.name)+'</b></span><span class="orow-v small">'+esc(adate(a.at))+'</span>'+
      '<span class="orow-p">'+esc(TROLE[a.role]||a.role)+(a.city?' · '+esc(a.city):'')+'</span><span class="tag">'+esc(TAPP[a.status])+'</span>'+
      '<span class="orow-x">'+(a.trial&&a.trial.due&&a.status==='trial'?'<span>تسليم التجربة '+esc(fdate(a.trial.due))+'</span>':'')+'</span></button></li>'; }
  function appBody(a){ var tr=a.trial||{};
      return '<div class="body"><div class="grid2"><div>'+
        '<div class="small muted">الأعمال</div><div class="links">'+(a.reel?'<a href="'+esc(a.reel)+'" target="_blank" rel="noopener" dir="ltr">'+esc(a.reel)+'</a>':'')+(a.links||[]).map(function(l){ return '<a href="'+esc(l)+'" target="_blank" rel="noopener" dir="ltr">'+esc(l)+'</a>'; }).join('')+'</div>'+
        '<div class="small muted" style="margin-top:10px">التفاصيل</div><div class="small">'+[a.tools&&'الأدوات: '+esc(a.tools),a.hours&&'ساعات أسبوعياً: '+a.hours,a.rate&&'الأجر المتوقع: '+esc(a.rate),a.gender&&'الجنس: '+(a.gender==='female'?'أنثى':'ذكر'),a.langs&&'اللغات: '+esc(a.langs),'<span dir="ltr">'+esc(a.email)+'</span>'+(a.phone?' · <span dir="ltr">'+esc(a.phone)+'</span>':'')].filter(Boolean).join('<br>')+'</div>'+
        (a.about?'<div class="small muted" style="margin-top:10px">عنه</div><pre>'+esc(a.about)+'</pre>':'')+'</div>'+
        '<div class="ofields" data-app="'+esc(a.id)+'"><div class="field"><label>المرحلة</label><select data-af="status">'+Object.keys(TAPP).map(function(s){ return '<option value="'+s+'"'+(s===a.status?' selected':'')+'>'+TAPP[s]+'</option>'; }).join('')+'</select></div>'+
          '<div class="crm"><b class="small">المهمة التجريبية</b><textarea data-af="trial.brief" placeholder="البريف: ما المطلوب بالتحديد">'+esc(tr.brief||'')+'</textarea><div class="row"><div class="field"><label>رابط المواد</label><input data-af="trial.link" dir="ltr" value="'+esc(tr.link||'')+'"></div><div class="field"><label>الموعد</label><input data-af="trial.due" type="date" value="'+esc(tr.due||'')+'"></div></div><div class="field"><label>النتيجة / رابط تسليمه</label><input data-af="trial.result" dir="auto" value="'+esc(tr.result||'')+'"></div>'+
            (tr.brief&&a.phone?'<a class="btn sm" target="_blank" rel="noopener" href="'+esc(waLink(a.phone,'مرحباً '+a.name+'، شكراً لاهتمامك بالانضمام لـ Eyeblink Studio. هذه مهمة تجريبية قصيرة:\n\n'+tr.brief+(tr.link?'\n\nالمواد: '+tr.link:'')+(tr.due?'\nالتسليم: '+tr.due:'')))+'">أرسل المهمة التجريبية عبر واتساب</a>':'')+'</div>'+
          (function(){ var iv=a.interview||{}; return '<div class="crm"><b class="small">المقابلة</b><p class="hint" style="margin:0">تُرسل الدعوة تلقائياً حين تكون المرحلة «مقابلة» وتحفظ الموعد والمنصة، وإذا غيّرتهما تُرسل من جديد</p>'+
            '<div class="row"><div class="field"><label>الموعد</label><input data-af="iv.at" type="datetime-local" value="'+esc(iv.at||'')+'"></div><div class="field"><label>التوقيت</label><select data-af="iv.tz">'+[['dxb','الإمارات'],['ruh','السعودية'],['dam','دمشق'],['cai','القاهرة']].map(function(o){ return '<option value="'+o[0]+'"'+((iv.tz||'dxb')===o[0]?' selected':'')+'>'+o[1]+'</option>'; }).join('')+'</select></div></div>'+
            '<div class="row"><div class="field"><label>المنصة</label><select data-af="iv.platform"><option value="">اختر</option>'+[['meet','Google Meet'],['zoom','Zoom'],['whatsapp','WhatsApp']].map(function(o){ return '<option value="'+o[0]+'"'+(iv.platform===o[0]?' selected':'')+'>'+o[1]+'</option>'; }).join('')+'</select></div><div class="field"><label>الرابط أو الرقم</label><input data-af="iv.link" dir="ltr" value="'+esc(iv.link||'')+'"></div></div>'+
            (iv.sentAt?'<span class="tag c-good">أُرسلت الدعوة · '+esc(new Date(iv.sentAt).toLocaleString('ar-u-nu-latn',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}))+'</span>':iv.mailFailed?'<span class="tag c-bad">تعذّر إرسال الدعوة، احفظ مرة أخرى</span>':'')+'</div>'; })()+
          '<div class="field"><label>ملاحظاتك</label><textarea data-af="notes">'+esc(a.notes||'')+'</textarea></div>'+
          '<div class="actions"><button class="btn sm primary" type="button" data-asave="'+esc(a.id)+'">حفظ</button>'+(a.status==='rejected'?(a.rejectMailAt?'<span class="tag">أُرسلت رسالة الاعتذار</span>':'<button class="btn sm" type="button" data-areject="'+esc(a.id)+'">أرسل رسالة الاعتذار</button>'):'')+(a.member?'<span class="tag c-good">انضم إلى الفريق</span>':'<button class="btn sm" type="button" data-aaccept="'+esc(a.id)+'">اقبله وأعدّ حسابه</button>')+'<button class="btn sm danger" type="button" data-adel="'+esc(a.id)+'">حذف</button></div></div></div></div>';
  }
  function teamSettings(){ var s=TEAM.settings||{}, roles=s.roles||[];
    return '<form class="sec" id="tSet"><h3>التوظيف</h3><p class="hint">حين يكون مفعّلاً تستقبل صفحة <a href="/join" target="_blank" rel="noopener noreferrer" dir="ltr">eyeblinkstudio.com/join</a> الطلبات، وحين يكون متوقفاً تعرض «لا نستقبل طلبات حالياً»</p>'+
      '<label class="check"><input type="checkbox" name="open"'+(s.open?' checked':'')+'> نستقبل طلبات انضمام</label>'+
      '<div class="field"><label>الأدوار المطلوبة</label><div class="dpay">'+Object.keys(TROLE).map(function(r){ var on=roles.indexOf(r)>=0; return '<label class="dchip'+(on?' on':'')+'"><input type="checkbox" name="roles" value="'+r+'"'+(on?' checked':'')+'>'+TROLE[r]+'</label>'; }).join('')+'</div></div>'+
      '<div class="field"><label>خانات النموذج</label><p class="hint" style="margin:0">الاسم والبريد الإلكتروني إلزاميان دائماً، وكل خانة أخرى إما مخفية أو اختيارية أو إلزامية</p><div class="tfields">'+TFIELDS.map(function(x){ var v=(s.fields||{})[x[0]]||'optional'; return '<label class="tfrow"><span>'+x[1]+'</span><select name="f_'+x[0]+'">'+[['optional','اختيارية'],['required','إلزامية'],['hidden','مخفية']].map(function(o){ return '<option value="'+o[0]+'"'+(o[0]===v?' selected':'')+'>'+o[1]+'</option>'; }).join('')+'</select></label>'; }).join('')+'</div></div><div class="actions"><button class="btn primary" type="submit">حفظ</button><a class="btn" href="/join" target="_blank" rel="noopener noreferrer">افتح الصفحة</a></div></form>';
  }
  // the collaboration agreement: written from the member's role; studio can edit it before sending like any agreement
  var TPAY={usdt:['Binance Pay / USDT','Binance Pay / USDT'],wu:['ويسترن يونيون','Western Union'],bank:['حوالة بنكية','bank transfer'],wise:['Wise','Wise'],payoneer:['Payoneer','Payoneer'],shamcash:['شام كاش','Sham Cash'],local:['حوالة محلية','a local money transfer'],other:['','']};
  function payText(m,lang,fallback){ var p=m.pay||{}, en=lang==='en', k=TPAY[p.method]; if(!k) return fallback; var name=p.method==='other'?(p.details||fallback):k[en?1:0]; return name+(p.method!=='other'&&p.details?' ('+p.details+')':''); }
  function payFields(p){ p=p||{}; return '<div class="row"><div class="field"><label>طريقة صرف أجره (المتفق عليها)</label><select name="payMethod"><option value="">— حسب إعدادات المستندات —</option>'+Object.keys(TPAY).map(function(k){ return '<option value="'+k+'"'+(p.method===k?' selected':'')+'>'+(k==='other'?'طريقة أخرى':TPAY[k][0])+'</option>'; }).join('')+'</select></div><div class="field"><label>التفاصيل (المحفظة، الاسم والمدينة، الحساب…)</label><input name="payDetails" dir="auto" value="'+esc(p.details||'')+'"></div></div>'; }
  // staff: the approved contract terms (12 Nov 2026); probation and weekly hours are set for each member
  function staffClauses(lang,v){
    if(lang==='en') return [
      {h:'Subject',p:'The Second Party ('+v.member+') works for the First Party ('+v.studio+') as '+v.role+', from the date this contract is signed, according to the job description and the tasks the First Party assigns within the role'},
      {h:'Probation',p:'Probation lasts '+v.probation+' from the start date; during it either party may end this contract with 7 days’ notice'},
      {h:'Place and hours of work',p:'The Second Party works remotely, '+v.hours+' hours a week, is reachable during the agreed working hours, and replies immediately and responds quickly within them'},
      {h:'Salary',p:'The Second Party receives a monthly salary of '+v.salary+', paid within the first 5 days of the following month through '+v.payMethods+'. Tasks within the role earn no extra pay'},
      {h:'Performance',p:'The Second Party’s performance is reviewed regularly against clear goals set by the First Party. Repeated shortfalls after a written warning allow the First Party to end this contract'},
      {h:'Accounts and tools',p:'Work accounts, their passwords and work tools belong to the First Party; the Second Party uses them for work only and hands them all over when this contract ends'},
      {h:'Confidentiality',p:'The Second Party keeps all client data, prices, files and methods confidential, during this contract and after it without time limit'},
      {h:'No work for clients on its own account',p:'The Second Party does not offer its services directly to the First Party’s clients during this contract and for '+v.months+' months after it, without written consent'},
      {h:'Intellectual property',p:'Everything the Second Party produces within its role belongs to the First Party from the moment it is made'},
      {h:'Ending the contract',p:'After probation, either party may end this contract with 30 days’ written notice; the salary is paid up to the last working day. The First Party may end it at once for a serious breach of confidentiality or trust'},
      {h:'General',p:'Written messages through the team portal and email form part of this contract; no amendment is valid unless agreed in writing by both parties. Disputes are settled amicably first'}];
    return [
      {h:'موضوع العقد',p:'يعمل الطرف الثاني ('+v.member+') لدى الطرف الأول ('+v.studio+') في وظيفة '+v.role+'، ابتداءً من تاريخ توقيع هذا العقد، وفق الوصف الوظيفي وما يكلّفه به الطرف الأول ضمن طبيعة الوظيفة'},
      {h:'فترة التجربة',p:'تمتد فترة التجربة '+v.probation+' من تاريخ البدء، ولكل طرف خلالها إنهاء العقد بإشعار 7 أيام'},
      {h:'مكان العمل وأوقاته',p:'يعمل الطرف الثاني عن بُعد، بمعدل '+v.hours+' ساعة أسبوعياً، ويكون متاحاً للتواصل خلال ساعات العمل المتفق عليها، ويلتزم بالرد الفوري والاستجابة السريعة خلالها'},
      {h:'الراتب',p:'يتقاضى الطرف الثاني راتباً شهرياً قدره '+v.salary+'، يُصرف خلال أول 5 أيام من الشهر التالي عبر '+v.payMethods+'. ولا يستحق أجراً إضافياً عن المهام الداخلة في وظيفته'},
      {h:'الأداء والتقييم',p:'يُراجع أداء الطرف الثاني دورياً وفق أهداف واضحة يحددها الطرف الأول. وإذا تكرر التقصير بعد التنبيه الكتابي، يحق للطرف الأول إنهاء العقد'},
      {h:'الحسابات والأدوات',p:'تبقى حسابات العمل وكلمات مرورها وأدواته ملكاً للطرف الأول، ويستخدمها الطرف الثاني للعمل فقط، ويسلّمها كاملة عند انتهاء العقد'},
      {h:'السرية',p:'يلتزم الطرف الثاني بسرية كل ما يطّلع عليه من بيانات العملاء والأسعار والملفات وأساليب العمل، أثناء العقد وبعده دون حد زمني'},
      {h:'عدم العمل مع العملاء لحسابه',p:'لا يقدّم الطرف الثاني خدماته مباشرة لعملاء الطرف الأول، أثناء العقد ولمدة '+v.months+' شهراً بعده، إلا بموافقة كتابية'},
      {h:'الملكية الفكرية',p:'كل ما ينتجه الطرف الثاني في إطار وظيفته ملك للطرف الأول من لحظة إنتاجه'},
      {h:'إنهاء العقد',p:'بعد فترة التجربة، لكل طرف إنهاء العقد بإشعار كتابي قبل 30 يوماً، ويُصرف الراتب حتى آخر يوم عمل. ويحق للطرف الأول الإنهاء فوراً عند الإخلال الجسيم بالسرية أو الأمانة'},
      {h:'أحكام عامة',p:'المراسلات المكتوبة عبر بوابة الفريق والبريد الإلكتروني جزء من هذا العقد، ولا يُعتدّ بأي تعديل إلا كتابياً من الطرفين. وتُحلّ أي خلافات ودياً أولاً'}];
  }
  var PROB={1:['شهر واحد','one month'],2:['شهران','two months'],3:['ثلاثة أشهر','three months']};
  function staffFields(m,show){ return '<div class="field" data-salary'+(show?'':' hidden')+' style="max-width:170px"><label>فترة التجربة</label><select name="probation">'+[1,2,3].map(function(n){ return '<option value="'+n+'"'+((+m.probation||3)===n?' selected':'')+'>'+PROB[n][0]+'</option>'; }).join('')+'</select></div><div class="field" data-salary'+(show?'':' hidden')+' style="max-width:170px"><label>ساعات العمل بالأسبوع</label><input name="hours" type="number" min="5" max="60" dir="ltr" value="'+esc(m.hours||40)+'"></div>'; }
  function teamClauses(lang,v){
    if(lang==='en') return [
      {h:'Subject',p:'The Second Party ('+v.member+') works with the First Party ('+v.studio+') as an independent collaborator in '+v.role+', on tasks the First Party assigns through the team portal'},
      {h:'Nature of the relationship',p:'The Second Party works independently and is responsible for its own tools, time and legal and tax obligations; this agreement creates no employment or partnership. All obligations in it apply as soon as the Second Party accepts a task'},
      {h:'Offering and accepting a task',p:'Each task is offered through the team portal with its description, due date and fee. The Second Party may accept it or decline it within one hour of receiving it. Confirming receipt, starting work, or letting the hour pass without declining counts as acceptance. Once accepted, the task is a binding commitment on its full terms'},
      {h:'Withdrawing after acceptance',p:'The Second Party may not withdraw from an accepted task except for force majeure reported at once. Withdrawing without an acceptable reason, or not delivering, earns no fee for that task; all work done is handed over within 24 hours, and the First Party may end the collaboration'},
      {h:'Deadlines and delays',p:'The Second Party meets the agreed due date and reports any expected delay at least 24 hours ahead. Each day of unjustified delay deducts 10% of the task fee, up to 50%. A delay of more than three days without notice lets the First Party withdraw the task without a fee'},
      {h:'Communication',p:'The Second Party replies immediately and responds quickly to the First Party’s messages and notes throughout any task, and gives notice in advance of any time it will be unavailable'},
      {h:'Quality and review',p:'Work follows the brief and the First Party’s standards. Every version goes through internal review; review notes and client notes within the brief are carried out at no extra fee until approval. If a version still misses the brief after two review rounds through clear fault, the First Party may withdraw the task and pay a partial fee it sets by what is usable, or none'},
      {h:'Fees and payment',p:'Each task’s fee is set before it is accepted and changes only by written agreement. It is due once the First Party approves the task and paid within '+v.payDays+' days of approval through '+v.payMethods},
      {h:'No subcontracting',p:'The Second Party does not pass a task, or any part of it, to anyone else without the First Party’s written consent'},
      {h:'Confidentiality',p:'The Second Party keeps everything it sees confidential — client identities, files, footage, prices and methods — during the collaboration and after it without time limit, and shares no file with any third party'},
      {h:'No direct contact with clients',p:'The Second Party does not contact the First Party’s clients about any work, nor offer them its services directly, during the collaboration and for '+v.months+' months after it, without written consent. In breach, it compensates the First Party at least the value of the work it obtained from that client'},
      {h:'Intellectual property',p:'All rights in work produced within tasks pass to the First Party when its fee is paid, and the Second Party confirms the work is original. It may show it only with written permission, after the client has published it, and without naming the client unless allowed'},
      {h:'Licensed material and tools',p:'The Second Party uses only licensed software and material or what the First Party provides, and adds no music, footage, fonts or AI-generated elements without confirming their licence and telling the First Party'},
      {h:'Files',p:'The Second Party hands over final and open project files on request, and deletes client files from its devices 30 days after a task is approved unless asked otherwise'},
      {h:'Ending the collaboration',p:'Either party may end the collaboration with 7 days’ written notice, finishing or handing over accepted tasks; approved work is paid. The First Party may end it at once for a breach of confidentiality, contact with clients or withdrawal from tasks. Confidentiality, ownership and no-contact terms survive the end'},
      {h:'General',p:'Messages through the team portal, email and agreed messaging apps form part of this agreement; no amendment is valid unless agreed in writing by both parties. Disputes are settled amicably first'}];
    return [
      {h:'موضوع الاتفاقية',p:'يتعاون الطرف الثاني ('+v.member+') مع الطرف الأول ('+v.studio+') بصفته متعاوناً مستقلاً في مجال '+v.role+'، على أساس مهام يكلّفه بها الطرف الأول تباعاً عبر بوابة الفريق'},
      {h:'طبيعة العلاقة',p:'يعمل الطرف الثاني مستقلاً، ويتحمّل مسؤولية أدواته ووقته والتزاماته القانونية والضريبية، ولا تُنشئ هذه الاتفاقية علاقة عمل أو شراكة. وتسري عليه مع ذلك جميع الالتزامات الواردة فيها بمجرد قبوله أي مهمة'},
      {h:'عرض المهمة وقبولها',p:'تُعرض كل مهمة عبر بوابة الفريق مع وصفها وموعد تسليمها وأجرها. وللطرف الثاني قبولها أو الاعتذار عنها خلال ساعة واحدة من وصولها. ويُعدّ تأكيد الاستلام أو البدء بالعمل أو مرور الساعة دون اعتذار قبولاً للمهمة. وبعد القبول تصبح المهمة التزاماً واجب التنفيذ بشروطها كاملة'},
      {h:'الانسحاب بعد القبول',p:'لا يحق للطرف الثاني الانسحاب من مهمة قبلها إلا لظرف قاهر يُبلَّغ به فوراً. وإذا انسحب دون عذر مقبول أو لم يسلّم، فلا يستحق أجراً عنها، ويلتزم بتسليم كل ما أُنجز من ملفات خلال 24 ساعة، ويحق للطرف الأول إنهاء التعاون'},
      {h:'المواعيد والتأخير',p:'يلتزم الطرف الثاني بموعد التسليم المتفق عليه، ويُبلغ بأي تأخير متوقع قبل 24 ساعة على الأقل. ويُخصم 10% من أجر المهمة عن كل يوم تأخير غير مبرَّر، بحد أقصى 50%. وإذا تجاوز التأخير ثلاثة أيام دون إبلاغ، يحق للطرف الأول سحب المهمة دون أجر'},
      {h:'التواصل والاستجابة',p:'يلتزم الطرف الثاني بالرد الفوري والاستجابة السريعة لرسائل الطرف الأول وملاحظاته طوال تنفيذ أي مهمة، ويُبلغ مسبقاً عن أي فترة لا يكون فيها متاحاً'},
      {h:'الجودة والمراجعة',p:'يُنفَّذ العمل وفق البريف ومعايير الطرف الأول. وتمر كل نسخة بمراجعة داخلية، وتُنفَّذ ملاحظاتها وملاحظات العميل ضمن البريف دون أجر إضافي حتى الاعتماد. وإذا لم تطابق النسخة البريف بعد جولتي مراجعة بسبب تقصير واضح، يحق للطرف الأول سحب المهمة، وصرف أجر جزئي يقدّره بحسب ما يمكن استخدامه منها أو عدم صرفه'},
      {h:'الأجور والدفع',p:'يُحدَّد أجر كل مهمة قبل قبولها، ولا يتغير إلا باتفاق مكتوب. ويُستحق بعد اعتماد المهمة من الطرف الأول، ويُصرف خلال '+v.payDays+' أيام من الاعتماد عبر '+v.payMethods},
      {h:'عدم الإسناد للغير',p:'لا يُسند الطرف الثاني المهمة أو أي جزء منها لشخص آخر دون موافقة كتابية من الطرف الأول'},
      {h:'السرية',p:'يلتزم الطرف الثاني بسرية كل ما يطّلع عليه، من هوية العملاء والملفات واللقطات والأسعار وأساليب العمل، أثناء التعاون وبعده دون حد زمني، ولا يشارك أي ملف مع طرف ثالث'},
      {h:'عدم التواصل المباشر مع العملاء',p:'لا يتواصل الطرف الثاني مع عملاء الطرف الأول بشأن أي عمل، ولا يقدّم لهم خدماته مباشرة، أثناء التعاون ولمدة '+v.months+' شهراً بعده، إلا بموافقة كتابية. وعند الإخلال يلتزم بتعويض الطرف الأول بما لا يقل عن قيمة الأعمال التي حصل عليها من ذلك العميل'},
      {h:'الملكية الفكرية',p:'تنتقل جميع حقوق ما يُنفَّذ ضمن المهام إلى الطرف الأول عند صرف أجره، ويقرّ الطرف الثاني بأن عمله أصلي. ولا يعرضه في أعماله إلا بإذن كتابي وبعد نشره من العميل، ودون ذكر اسم العميل ما لم يُسمح بذلك'},
      {h:'المواد المرخّصة والأدوات',p:'يستخدم الطرف الثاني برامج ومواد مرخّصة فقط أو ما يوفّره الطرف الأول، ولا يضيف موسيقى أو لقطات أو خطوطاً أو عناصر مولّدة بالذكاء الاصطناعي دون التأكد من ترخيصها وإبلاغ الطرف الأول'},
      {h:'الملفات',p:'يسلّم الطرف الثاني الملفات النهائية وملفات المشروع المفتوحة عند الطلب، ويحذف ملفات العملاء من أجهزته بعد 30 يوماً من اعتماد المهمة ما لم يُطلب منه غير ذلك'},
      {h:'إنهاء التعاون',p:'لكل طرف إنهاء التعاون بإشعار كتابي قبل 7 أيام، مع إتمام المهام المقبولة أو تسليم ما أُنجز منها، ويُصرف أجر ما اعتُمد. ويحق للطرف الأول الإنهاء فوراً عند الإخلال بالسرية أو التواصل مع العملاء أو الانسحاب من المهام. وتبقى بنود السرية والملكية وعدم التواصل سارية بعد الإنهاء'},
      {h:'أحكام عامة',p:'تُعدّ المراسلات عبر بوابة الفريق والبريد الإلكتروني وتطبيقات المراسلة المعتمدة جزءاً من هذه الاتفاقية، ولا يُعتدّ بأي تعديل إلا كتابياً من الطرفين. وتُحلّ أي خلافات ودياً أولاً'}];
  }
  function issueContract(m,b,quiet){ var staff=m.type==='staff'; if(staff&&!(m.salary&&m.salary.amount)){ toast('أدخل راتبه الشهري أولاً (النوع والراتب)',true); return quiet?Promise.resolve(''):undefined; } var S=dset(), lang=m.lang==='en'?'en':'ar', role=lang==='en'?m.role:(TROLE[m.role]||m.role);
    var body={lang:lang,kind:staff?'staff':'freelance',title:(staff?(lang==='en'?'Employment · ':'وظيفة · '):(lang==='en'?'Independent collaboration · ':'تعاون مستقل · '))+role,summary:'',client:{name:m.name,company:'',place:'',contact:m.phone||'',email:m.email},studio:{name:S.studioName,place:S.studioPlace,contact:S.studioContact},items:[],cur:'$',
      includes:[],excludes:[],payMethods:'',notes:'',clauses:staff?staffClauses(lang,{member:m.name,studio:S.studioName,role:role,months:12,payMethods:payText(m,lang,S.payMethods),salary:pfmt(m.salary.amount,m.salary.cur),probation:(PROB[m.probation||3]||PROB[3])[lang==='en'?1:0],hours:m.hours||40}):teamClauses(lang,{member:m.name,studio:S.studioName,role:role,payDays:7,months:12,payMethods:payText(m,lang,S.payMethods)})};
    b.disabled=true; return api('/docs','POST',{action:'issue',type:'team',key:'member:'+m.email,doc:body}).then(function(j){ if(!j.ok) throw new Error(j.error);
      m.contract={token:j.doc.token,no:j.doc.no,signedAt:null}; var url=location.origin+'/team-agreement/'+j.doc.token;
      if(quiet) return url;
      showCreds({title:'اتفاقية التعاون جاهزة',lines:[['الرابط',url]],msg:'مرحباً '+m.name+'، هذه اتفاقية التعاون مع Eyeblink Studio. اقرأها ووقّعها من الرابط، وبعدها تُفتح لك مهامك في بوابة الفريق:\n'+url,phone:m.phone,open:url}); renderTeam(); })
      .catch(function(e){ b.disabled=false; toast('تعذّر إنشاء الاتفاقية',true); if(quiet) throw e; }); }
  // a small sheet with what to send (login details, agreement link): copy, WhatsApp
